import type { SkillTemplate, CommandTemplate } from '../types.js';


// Reference: full schema for the Step 5.5 archive run summary. Migrated from the overlay
// and RECONCILED to the B1 baselines (orbit-archive-modifications + orbit-conventions):
// unresolved_markers is an ARRAY; sync delta counts sit directly under sync_specs; exactly
// three user_decision values (abort writes no summary); flat audit_skipped_via_flag; orbit
// vocabulary throughout (no opsx/openspec-era residue).
const ARCHIVE_SUMMARY_SCHEMA_REFERENCE = `# Reference: archive run-summary schema

The orbit additions to \`/orbit:archive\` write a JSON summary to \`orbit/changes/archive/<YYYY-MM-DD>-<change-name>/.orbit-runs/archive-<TS>.json\` after a successful archive operation (the \`<YYYY-MM-DD>-\` prefix is added by upstream's archive move step). An aborted archive writes NO summary.

## Universal spine inheritance

This schema inherits the 6-field **universal spine** from \`orbit-conventions\`'s \`Internal-run JSON summary format\` requirement (see \`orbit/specs/orbit-conventions/spec.md\`):

- \`command\` (here: \`"archive"\`)
- \`timestamp\` (ISO-8601 UTC; JSON field \`YYYY-MM-DDTHH:MM:SSZ\`; filename \`<TS>\` token \`YYYY-MM-DDTHH-MM-SSZ\` with colons replaced by hyphens for filesystem safety)
- \`change\` (change name string)
- \`final_assessment\` (narrative of what was archived, e.g., \`"Archived <change-name> to <archive_path>."\`)
- \`next_recommended\` (verbatim recommendation, e.g., \`"Change archived. Run /orbit:new or /orbit:explore to start the next change, or /orbit:audit-drift for a project-wide drift check."\`)
- \`kind: "lifecycle"\` (archive is THE lifecycle command per the kind taxonomy — transitions a change out of the active set)

The schema below documents the per-command extensions ADDED to that spine (\`archive_path\`, \`audit\`, \`sync_specs\`, \`unresolved_markers\`, \`user_decision\`, \`warnings\`), per the \`kind: "lifecycle"\` extensions in \`orbit-conventions\`, plus the \`consent\` field (D1) and the conditional \`gate_overridden\` (C1) and \`fingerprint_overridden\` / \`fingerprints_unverified\` (C2) fields.

**Note on \`sync_specs\`**: this field reports the result of the archive flow invoking the \`orbit-sync-specs\` upstream primitive (kept upstream-verbatim per \`orbit-conventions\`' \`Generated-file disposition\`).

## Schema

\`\`\`json
{
  "command": "archive",
  "timestamp": "<ISO-8601>",
  "change": "<change-name>",
  "final_assessment": "<narrative of what was archived>",
  "next_recommended": "Change archived. Run /orbit:new or /orbit:explore to start the next change, or /orbit:audit-drift for a project-wide drift check.",
  "kind": "lifecycle",
  "archive_path": "orbit/changes/archive/<YYYY-MM-DD>-<change-name>/",
  "audit": {
    "ran": true | false,
    "failure_reason": "<text or null>",
    "findings_summary": { "critical": 0, "warning": 0, "suggestion": 0 },
    "summary_path": "<path to the audit-drift-<TS>.json summary, or null if not run>"
  },
  "audit_skipped_via_flag": true,
  "sync_specs": {
    "ran": true | false,
    "skipped_reason": "<text or null>",
    "capabilities_updated": ["<capability name>"],
    "added": 0,
    "modified": 0,
    "removed": 0,
    "renamed": 0
  },
  "unresolved_markers": ["<file>:<line> — <marker text>"],
  "user_decision": "proceeded_with_no_critical" | "proceeded_despite_critical" | "audit_skipped_via_flag",
  "consent": "user-invoked" | "prompted",
  "gate_overridden": { "gate": "review-system", "state": "<unpassed|stale>", "reason": "<gate reason at decision time>" },
  "fingerprint_overridden": [
    { "capability": "<name>", "requirement": "<name>", "base_hash": "sha256:<hex>", "live_hash": "sha256:<hex>" }
  ],
  "fingerprints_unverified": [
    { "capability": "<name>", "requirement": "<name>" }
  ],
  "warnings": [
    "<text — e.g., 'Archived with 2 incomplete artifacts'>"
  ]
}
\`\`\`

## Field notes

- **\`audit.ran\`** = \`false\` either because \`--skip-audit\` was set (then the top-level \`audit_skipped_via_flag: true\` is recorded) or because audit-drift failed (then \`failure_reason\` is set). The two cases are disambiguated by those flags.
- **\`audit.findings_summary\`** mirrors the audit-drift run summary's counts; the full audit detail lives at the path in \`audit.summary_path\`.
- **\`audit_skipped_via_flag\`** (top-level boolean): recorded as \`true\` only when \`/orbit:archive --skip-audit\` was used; omit the field otherwise. This is the flat field the skill body and the \`orbit-archive-modifications\` baseline require — it is NOT nested inside \`audit\`.
- **\`sync_specs.capabilities_updated\`** lists capability names whose \`orbit/specs/<capability>/spec.md\` was edited; the delta counts (\`added\`/\`modified\`/\`removed\`/\`renamed\`) sit DIRECTLY under \`sync_specs\`, mirroring \`orbit-conventions\`' canonical lifecycle example.
- **\`unresolved_markers\`** is an ARRAY of the \`@review:\` markers still present when the archive proceeded (empty array when none) — one \`"<file>:<line> — <marker text>"\` entry per marker. Marker-prompt outcomes that halt the archive write no summary at all.
- **\`user_decision\`** captures the AUDIT-drift prompt decision and has exactly three values: \`proceeded_with_no_critical\` (clean audit or warnings only), \`proceeded_despite_critical\` (user explicitly proceeded past CRITICAL findings), \`audit_skipped_via_flag\` (\`--skip-audit\` used). An abort at the critical-findings prompt cancels the archive and writes no summary.
- **\`consent\`** (D1, per \`orbit-lifecycle-consent\`) records the invocation's consent story from the Step 0 provenance check: \`"user-invoked"\` (user-typed \`/orbit:archive\`, or a user-typed \`/orbit:bulk-archive\` whose flow confirmed the batch) or \`"prompted"\` (AI-mediated arrival, consent prompt fired, user proceeded). Exactly two values — a consent Abort writes NO summary. REQUIRED on every post-capability archive emit; absence is the audit-drift tripwire condition. DISTINCT from \`user_decision\` (audit outcome), \`gate_overridden\` (cadence override), and the fingerprint fields (content guard).
- **\`gate_overridden\`** (C1) is DISTINCT from \`user_decision\` (which is the audit-drift outcome): it is present ONLY when the \`review-system\` gate was unpassed/stale at archive and the user chose **Proceed anyway** at the gate inflection prompt (Step 3.4); shape \`{gate, state, reason}\` captured at decision time. Absent when no gate override occurred.
- **\`fingerprint_overridden\`** (C2) is present ONLY when the Step 3.45 fingerprint check reported \`diverged\` requirement(s) and the user chose **Proceed anyway** at the divergence inflection prompt — one \`{capability, requirement, base_hash, live_hash}\` entry per diverged requirement, captured at decision time. Absent when no fingerprint override occurred; REQUIRED when proceed-anyway was chosen. DISTINCT from \`gate_overridden\` (review-cadence override) and \`user_decision\` (audit-drift outcome).
- **\`fingerprints_unverified\`** (C2) is present ONLY when the archive proceeded past requirement(s) whose fingerprint status was \`unverified\` (no base recorded — e.g. a hand-authored or pre-C2 delta) — one \`{capability, requirement}\` entry each. Absent when every touched requirement was verified.
- **\`warnings\`** captures the upstream warning surfaces (incomplete artifacts, incomplete tasks, sync skipped) — kept human-readable since they vary in shape.
`;

export function getArchiveChangeSkillTemplate(): SkillTemplate {
  return {
    name: 'orbit-archive-change',
    description: 'Archive a completed change in the experimental workflow. Use when the user wants to finalize and archive a change after implementation is complete.',
    instructions: `Archive a completed change in the experimental workflow.

**Input**: Optionally specify a change name. If omitted, check if it can be inferred from conversation context. If vague or ambiguous you MUST prompt for available changes.

**Steps**

1. **If no change name provided, prompt for selection**

   Run \`orbit list --json\` to get available changes. Use the **AskUserQuestion tool** to let the user select.

   Show only active changes (not already archived).
   Include the schema used for each change if available.

   **IMPORTANT**: Do NOT guess or auto-select a change. Always let the user choose.

2. **Check artifact completion status**

   Run \`orbit status --change "<name>" --json\` to check artifact completion.

   Parse the JSON to understand:
   - \`schemaName\`: The workflow being used
   - \`artifacts\`: List of artifacts with their status (\`done\` or other)

   **If any artifacts are not \`done\`:**
   - Display warning listing incomplete artifacts
   - Use **AskUserQuestion tool** to confirm user wants to proceed
   - Proceed if user confirms

3. **Check task completion status**

   Read the tasks file (typically \`tasks.md\`) to check for incomplete tasks.

   Count tasks marked with \`- [ ]\` (incomplete) vs \`- [x]\` (complete).

   **If incomplete tasks found:**
   - Display warning showing count of incomplete tasks
   - Use **AskUserQuestion tool** to confirm user wants to proceed
   - Proceed if user confirms

   **If no tasks file exists:** Proceed without task-related warning.

4. **Assess delta spec sync state**

   Check for delta specs at \`orbit/changes/<name>/specs/\`. If none exist, proceed without sync prompt.

   **If delta specs exist:**
   - Compare each delta spec with its corresponding main spec at \`orbit/specs/<capability>/spec.md\`
   - Determine what changes would be applied (adds, modifications, removals, renames)
   - Show a combined summary before prompting

   **Prompt options:**
   - If changes needed: "Sync now (recommended)", "Archive without syncing"
   - If already synced: "Archive now", "Sync anyway", "Cancel"

   If user chooses sync, use Task tool (subagent_type: "general-purpose", prompt: "Use Skill tool to invoke orbit-sync-specs for change '<name>'. Delta spec analysis: <include the analyzed delta spec summary>"). Proceed to archive regardless of choice.

5. **Perform the archive**

   Create the archive directory if it doesn't exist:
   \`\`\`bash
   mkdir -p orbit/changes/archive
   \`\`\`

   Generate target name using current date: \`YYYY-MM-DD-<change-name>\`

   **Check if target already exists:**
   - If yes: Fail with error, suggest renaming existing archive or using different date
   - If no: Move the change directory to archive

   \`\`\`bash
   mv orbit/changes/<name> orbit/changes/archive/YYYY-MM-DD-<name>
   \`\`\`

6. **Display summary**

   Show archive completion summary including:
   - Change name
   - Schema that was used
   - Archive location
   - Whether specs were synced (if applicable)
   - Note about any warnings (incomplete artifacts/tasks)

**Output On Success**

\`\`\`
## Archive Complete

**Change:** <change-name>
**Schema:** <schema-name>
**Archived to:** orbit/changes/archive/YYYY-MM-DD-<name>/
**Specs:** ✓ Synced to main specs (or "No delta specs" or "Sync skipped")

All artifacts complete. All tasks complete.
\`\`\`

**Guardrails**
- Always prompt for change selection if not provided
- Use artifact graph (orbit status --change <name> --json) for completion checking
- Don't block archive on warnings - just inform and confirm
- Preserve .openspec.yaml when moving to archive (it moves with the directory)
- Show clear summary of what happened
- If sync is requested, use orbit-sync-specs approach (agent-driven)
- If delta specs exist, always run the sync assessment and show the combined summary before prompting

---

# Orbit additions

The sections below describe orbit-specific additions on top of upstream's archive flow. The upstream content above is unchanged. Orbit adds a **consent check at entry** (D1), a **pre-archive \`audit-drift\` sweep**, a \`--skip-audit\` opt-out, an **unresolved \`@review:\` marker warning**, a **base-fingerprint divergence check** (C2), an **archive run summary** written to \`.orbit-runs/\`, and a small set of edge-case behaviors.

## Four execution disciplines (apply throughout this command)

**Read-before-reference (authoring-time)**. The archive run summary cites the pre-archive audit findings, user decision, and sync-specs results. Read the audit-drift output and the sync-specs assessment before writing the summary — don't infer counts from intent. The summary becomes the audit trail for the archived change; false claims corrupt later inspection.

**Change completeness (modification-time)**. The archive flow modifies multiple artifacts: it moves the change directory, runs \`sync-specs\` (which writes to baseline), and writes the archive run summary. Apply these fully: a moved change should not leave dangling references in baseline; a sync-specs run should not leave delta-only requirements unreflected in baseline. Sweep after each step to confirm completion before proceeding to the next.

**Pushback (review-time)**. The pre-archive audit produces findings. Before presenting them to the user, verify each against current state (audit-drift's own pushback discipline applies, but apply a second-pass check at the archive layer): is the finding still applicable given any commits since the audit ran in the current session? Stale findings get a note in the summary, not a re-prompt.

**No-chaining (turn boundary)**. Invoke at most the orbit workflow commands the user's message explicitly requests — one command per explicit request; recommend, never invoke. Completing a command ENDS the turn at the position readout and the engine's eligibility line; blanket delegation ("take it through review") covers work WITHIN the requested command, never the next one — gate \`passed\` means *eligible*, not *commanded*.

## NEW Step 0 — Consent at entry (provenance rule, per \`orbit-lifecycle-consent\`)

BEFORE any other step — before the Step 1.5 marker scan, the Step 3.4 gate prompt, and every write. Archive is a consent-scoped command (the \`review-system\` gate carries \`consent: user-invoked\`); consent asks "should we be here at all", the anomaly prompts (gate, fingerprint, audit) ask "is the state sound".

**Ordering invariant**: provenance is CLASSIFIED at entry (a fact about the triggering turn); the consent prompt itself — and the era stamp below — fire AFTER read-only discovery (change selection; the read-only look at \`orbit/changes/<name>/specs/\` that supplies the write preview) and BEFORE any write or anomaly prompt. Read-only steps never require consent; writes always follow it.

Determine invocation provenance — an observable transcript fact, never a judgment of delegated intent:

- **User-invoked**: the triggering turn contains an explicit user invocation — the typed \`/orbit:archive\` command, or an unambiguous same-turn prose request naming the act ("archive it"). Proceed with ZERO added prompts (only the anomaly prompts may interrupt); the run summary records \`consent: "user-invoked"\`.
- **AI-mediated**: everything else — delegation phrases ("finish the cadence"), inference ("continue"), a handoff document, or an eligibility readout pointing here. Fire a consent **AskUserQuestion** BEFORE any of the command's writes: the position readout, what the archive will write (N deltas across M capabilities synced to baseline + the change moved to archive — from a read-only look at \`orbit/changes/<name>/specs/\`), and exactly two options — **Proceed** / **Abort**. Proceed records \`consent: "prompted"\` in the run summary; **Abort leaves no baseline write, no sync, no move, and no run summary**.
- **When provenance is uncertain, treat the arrival as AI-mediated** — erring toward one extra click, never toward a silent proceed.

**Consent-era stamp (migrate-on-touch)**: once consent is established (user-typed provenance, or Proceed at the prompt), read the change's \`.openspec.yaml\`. If it lacks \`schema_version\`, stamp \`consent_era_from: <current UTC timestamp, YYYY-MM-DDTHH:MM:SSZ>\` into it (add-only; never overwrite an existing stamp) — this marks a pre-capability change as tripwire-covered from this touch onward.

**Sync inheritance (no double-prompt)**: the sync-specs step this flow invokes (upstream Step 4) inherits THIS flow's consent — it never fires a separate consent prompt.

## NEW Step 1.5 — Unresolved \`@review:\` marker warning

After upstream Step 1 (selection) but before Step 2 (artifact completion check):

Grep the change directory for \`@review:\` markers:

\`\`\`bash
grep -rn "@review:" orbit/changes/<change-name>/
\`\`\`

If any markers are found, warn:

\`\`\`
N unaddressed \`@review:\` markers will land in archive — convert to \`@todo:\` or address before archiving?
\`\`\`

Prompt via \`AskUserQuestion\`:

- **Address now** — halt the archive; user runs \`/orbit:address-reviews orbit/changes/<change-name>/\` to resolve before re-invoking.
- **Convert to \`@todo:\`** — run a bulk transform replacing each \`@review:\` with \`@todo:\` in place (preserves the content as known follow-up rather than unresolved review).
- **Proceed** — archive with the markers in place; record this decision in the archive run summary.

If no markers, proceed without prompting.

## NEW Step 3.4 — review-system gate inflection prompt (C1)

After upstream Step 3 (task-completion check) but before the audit sweep (Step 3.5) — the gate prompt fires FIRST per the gated-phase contract:

Query the gate: \`orbit status --change "<change-name>" --json\` and read the \`gates[]\` entry with \`id: "review-system"\` (there is NO \`orbit instructions archive\` phase — the archive workflow sources gate state from \`status\`). If that gate's \`state\` is \`unpassed\` or \`stale\`, fire the inflection prompt via **AskUserQuestion** with the gate's \`reason\` and the top-level \`next_command\` shown:

- **Address the gate** — halt; run the canonical \`next_command\` (e.g. \`/orbit:review-external --as system <change>\`).
- **Proceed anyway** — continue the archive; record \`gate_overridden: {gate: "review-system", state, reason}\` in the archive run summary (captured at decision time).
- **Abort** — cancel the archive; no move, no sync-specs, no summary.

The gate NEVER hard-blocks (apply-parity): the engine reports, the skill prompts, the user decides, the trail records. If \`review-system\` is \`passed\` (or the schema declares no such gate), proceed without prompting. This gate prompt is DISTINCT from the Step 0 consent prompt (consent asks "should we be here at all"; this asks "is the state sound"), the fingerprint prompt (Step 3.45), and the audit-drift prompt (Step 3.5); a single invocation MAY fire consent first and the anomaly prompts after (gate, then fingerprints, then audit).

## NEW Step 3.45 — Base-fingerprint divergence check (C2)

After the Step 3.4 gate prompt resolves but before the Step 3.5 audit sweep. **This check is the
workflow path's ONLY guard layer**: this flow applies deltas agent-driven (sync-specs at Step 4)
and moves with \`mv\` (Step 5), so the engine guard inside the \`orbit archive\` CLI never runs
here (per \`orbit-base-fingerprints\`' two-layer coverage model).

Run:

\`\`\`bash
orbit fingerprint "<change-name>" --check --json
\`\`\`

and branch on the per-requirement \`status\` values:

| Check state | Action |
|---|---|
| any \`diverged\` | Fire the divergence inflection prompt (below). |
| \`unverified\` present, none \`diverged\` | Prompt via \`AskUserQuestion\`: proceed / abort — "can't verify — no base recorded" (hand-authored or pre-C2 delta). Proceeding records \`fingerprints_unverified: [{capability, requirement}]\` in the run summary. |
| all \`verified\` (or the change touches no existing requirements) | Proceed silently; no prompt, no summary fields. |
| any \`missing\` | The touched requirement no longer exists in baseline (a sibling renamed/removed it). Include it in the divergence prompt if one fires; otherwise halt and show the check output — the sync would fail on it regardless. |

### Divergence inflection prompt (\`AskUserQuestion\`)

Present each diverged requirement (capability / requirement / \`base_hash\` → \`live_hash\`) plus
the divergence detail: read the LIVE requirement block from \`orbit/specs/<capability>/spec.md\`
and the delta's MODIFIED block, and show what the sync would overwrite — content present live but
absent from the delta is exactly what would be destroyed. When \`unverified\` requirements exist
alongside diverged ones, list them too (proceeding records both summary fields). Exactly three
options:

- **Reconcile** — halt the archive. Print the guided-manual instructions IN THIS ORDER: (1)
  hand-edit the delta spec(s) under \`orbit/changes/<name>/specs/\` to incorporate the divergent
  live content shown; (2) re-stamp via \`orbit fingerprint <name> --refresh\`. Then re-invoke
  \`/orbit:archive\`. (A refresh WITHOUT the edit re-opens the loss hole — an accepted,
  deliberate-only Phase-0 footgun; the Phase-1 3-way merge removes it.)
- **Proceed anyway** — continue the archive flow past the check (no CLI flag is involved on this
  agent-driven path; \`--override-fingerprints\` is the equivalent for CLI-direct \`orbit archive\`
  runs). Record \`fingerprint_overridden: [{capability, requirement, base_hash, live_hash}]\` in
  the archive run summary, captured at decision time.
- **Abort** — cancel the archive; no move, no sync-specs, no summary.

This prompt is DISTINCT from the Step 3.4 gate prompt and the Step 3.5 audit prompt.

## NEW Step 3.5 — Pre-archive audit-drift sweep

After upstream Step 3 (task-completion check) but before Step 4 (sync-specs):

**Unless \`--skip-audit\` is set**, invoke \`/orbit:audit-drift\` as a library function with context \`pre-archive\` and the current change name. Wait for the findings.

### Branching on audit findings

| Audit state | Action |
|---|---|
| **≥1 CRITICAL findings** | Prompt user via \`AskUserQuestion\`: "Address now / Proceed with archive / Abort?" Show the full audit findings to inform the choice. |
| **No CRITICAL, only WARNING/SUGGESTION** | Proceed without prompting; warnings logged in the archive run summary. |
| **No findings** | Proceed without prompting; clean audit recorded in summary. |
| **Audit failed to run** (parse error, internal exception) | Proceed with a warning. Archive run summary records \`audit.ran: false\` with the failure reason. Do NOT block on audit-tool failures. |

### Prompt outcomes (for the ≥1 CRITICAL case)

- **Address now** → archive does not proceed. User fixes the drift issues and re-invokes \`/orbit:archive\`. No summary written this run.
- **Proceed with archive** → archive proceeds normally. Summary records \`user_decision: proceeded_despite_critical\`.
- **Abort** → archive is cancelled. No move, no sync-specs, no summary.

### \`--skip-audit\` flag

When \`/orbit:archive --skip-audit <name>\` is invoked, the entire Step 3.5 audit is skipped. The archive run summary records \`audit_skipped_via_flag: true\`. Use case: the user has just run \`/orbit:audit-drift\` manually and doesn't need to repeat it.

## NEW Step 5.5 — Archive run summary

After upstream Step 5 (move-to-archive) completes successfully, write a JSON summary to:

\`\`\`
orbit/changes/archive/<YYYY-MM-DD>-<change-name>/.orbit-runs/archive-<TS>.json
\`\`\`

Where \`<YYYY-MM-DD>\` is the date prefix upstream's move step added (per \`mv orbit/changes/<name> orbit/changes/archive/YYYY-MM-DD-<name>\` at Step 5). The \`.orbit-runs/\` directory should be present already — it moved with the change content. If somehow absent, create it.

Full schema lives at \`references/archive-summary-schema.md\` — read that file when composing the summary.

## NEW Step 5.6 — Stage-line garnish in the completion readout (D-arc Stage D2)

When the archived change's metadata carries an \`architecture: {doc, stage}\` citation, the
completion readout (the "Archive Complete" summary) gains ONE stage line: after the move, run
\`orbit architecture status --json\` and render the cited stage's post-archive computed position —
e.g. \`stage d2-architect: now quiescent — completion is yours to ratify\`, or
\`stage d6-pr-lifecycle: still in-change — <other-change> remains active\`, or
\`stage d1-...: complete (ratified <date> by <who>)\` when the mark already composes. One line
riding the existing position render — no prompt, no doc edit, no new mechanism (D-d2-4: the
readout is the reminder; ratification happens in an architect session or by hand, never here).
Uncited changes see no stage line — their readout is byte-identical to pre-D2 behavior.

## \`.orbit-runs/\` moves with the change

Upstream Step 5's \`mv orbit/changes/<name> orbit/changes/archive/YYYY-MM-DD-<name>\` already moves the entire change directory, including \`.orbit-runs/\`. No additional handling required — \`.orbit-runs/\` is just a subdirectory of the change.

All prior internal-run summaries (\`review-*-*.json\`, \`audit-drift-*.json\`, \`address-reviews-*.json\`) and external-review findings (\`external-*.md\` + \`external-prompt-*-*.md\`) persist in the archived location at \`orbit/changes/archive/<YYYY-MM-DD>-<change-name>/.orbit-runs/\`.

## Edge cases

### Already archived

If \`orbit/changes/archive/<YYYY-MM-DD>-<change-name>/\` already exists when the user invokes \`/orbit:archive <change-name>\` (i.e., a same-day prior archive for the same change name):

Halt with a clear error:

\`\`\`
Change <name> is already at orbit/changes/archive/<YYYY-MM-DD>-<name>/.
\`\`\`

Do NOT prompt to overwrite; the user must explicitly resolve the conflict (rename existing archive, use different date, etc.).

### audit-drift fails to run

Already covered in Step 3.5 — proceed with warning; summary records \`audit.ran: false\` + failure reason. Do NOT block on audit-tool failures.

## Audit is informational, not gate

Audit-drift findings are **informational** unless the user explicitly chooses to abort. The archive command does NOT:

- Attempt to resolve audit findings automatically (user's responsibility via \`/orbit:address-reviews\` or manual edit).
- Auto-invoke \`/orbit:review --as system\` even if it hasn't run for this change. System-mode review is the user's gate — their responsibility to run it before archiving if they want that signal.

This is a deliberate choice (per \`orbit-archive-modifications\`' \`Audit informational, not blocking by default\` requirement): users may legitimately archive with known drift (e.g., follow-up commit planned). orbit captures the decision in the summary for traceability, but doesn't override.`,
    references: [
      {
        name: 'archive-summary-schema.md',
        content: ARCHIVE_SUMMARY_SCHEMA_REFERENCE,
      },
    ],
    license: 'MIT',
    compatibility: 'Requires orbit CLI.',
    metadata: { author: 'openspec', version: '1.0' },
  };
}

export function getOrbitArchiveCommandTemplate(): CommandTemplate {
  return {
    name: 'ORBIT: Archive',
    description: 'Archive a completed change in the experimental workflow',
    category: 'Workflow',
    tags: ['workflow', 'archive', 'experimental'],
    content: `Archive a completed change (with pre-archive checks).

This command is a thin launcher: invoke the \`orbit-archive-change\` skill, passing along any arguments given with the command (e.g., \`/orbit:archive <name>\`). The skill carries the complete workflow instructions — upstream openspec behavior plus orbit's additions. Do not improvise the workflow from this file; load the skill.`
  };
}
